/**
 * 🔍️ M5a source sweep — takes the gesture-route and destructive-verb findings the descriptor
 * census reports and asks the PLUGIN SOURCE whether each one is already declared. The committed
 * `🔣️.json` descriptors predate every declaration written in this ticket (they are regenerated by
 * A3's queued sweep), so the descriptor census measures descriptor debt; this measures source debt,
 * which is what a worker can actually fix.
 *
 * Run: `bun .🧬semio/.../🐍️m5a-source-declaration-sweep.ts`
 */
import { readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { spawnSync } from "node:child_process";

const repoRoot = resolve(import.meta.dir, "../../../../../../..");
const censusPath = join(import.meta.dir, "🗑️generated/m5a-descriptor-census.txt");
const registry = JSON.parse(readFileSync(join(repoRoot, "🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/📇️registry/🤖️generated/🔌️plugins.json"), "utf8")) as Array<{ pluginId: string; cratePath: string }>;
const ownerRootOf = new Map(registry.map((entry) => [entry.pluginId, entry.cratePath.split("/").slice(0, -2).join("/")]));

/** 🔎️ Every `.rs` line under `dir` matching any of `patterns` (fixed strings). */
function grep(dir: string, patterns: string[]): string {
  const args = ["-rn", "--include=*.rs", "-F"];
  for (const pattern of patterns) args.push("-e", pattern);
  args.push(join(repoRoot, dir));
  const result = spawnSync("grep", args, { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  return result.stdout ?? "";
}

const census = readFileSync(censusPath, "utf8");

function findings(heading: string): Array<{ plugin: string; ids: string[] }> {
  const body = census.split(heading)[1]?.split("\n##")[0] ?? "";
  const rows: Array<{ plugin: string; ids: string[] }> = [];
  for (const line of body.trim().split("\n")) {
    const match = /^- \*\*(.+?)\*\*: (.+)$/.exec(line);
    if (!match) continue;
    const listed = match[2]!;
    const ids = listed.includes("(~") ? [...listed.matchAll(/([A-Za-z][\w.-]*) \(~/g)].map((entry) => entry[1]!) : listed.split(", ").map((entry) => entry.trim());
    rows.push({ plugin: match[1]!, ids });
  }
  return rows;
}

let openAudience = 0;
let openDestructive = 0;
console.log(`# m5a source declaration sweep — ${new Date().toISOString()}`);
console.log("");
console.log("## gesture routes: descriptor finding vs source declaration");
for (const row of findings("## gesture routes published to agents with no declaration")) {
  const dir = ownerRootOf.get(row.plugin);
  if (!dir) {
    console.log(`- ${row.plugin}: NOT IN REGISTRY`);
    continue;
  }
  const declared: string[] = [];
  const open: string[] = [];
  for (const id of row.ids) {
    const hits = grep(dir, [`action_audience("${id}"`, `"${id}"`]);
    const isDeclared = hits.split("\n").some((line) => line.includes(`action_audience("${id}"`) || (line.includes(`"${id}"`) && (line.includes("input_event") || line.includes(".chrome()"))));
    (isDeclared ? declared : open).push(id);
  }
  openAudience += open.length;
  console.log(`- **${row.plugin}** — declared ${declared.length}/${row.ids.length}${open.length ? `; OPEN: ${open.join(", ")}` : ""}`);
}

console.log("");
console.log("## destructive-class verbs: descriptor finding vs source declaration");
for (const row of findings("## destructive-looking verbs with effects.destructive = false")) {
  const dir = ownerRootOf.get(row.plugin);
  if (!dir) {
    console.log(`- ${row.plugin}: NOT IN REGISTRY`);
    continue;
  }
  const open: string[] = [];
  let declared = 0;
  for (const id of row.ids) {
    const hits = grep(dir, [`action_destructive("${id}"`, `"${id}"`]);
    const isDeclared = hits.split("\n").some((line) => line.includes(`action_destructive("${id}"`) || (line.includes(`"${id}"`) && line.includes(".destructive()")));
    if (isDeclared) declared += 1;
    else open.push(id);
  }
  openDestructive += open.length;
  console.log(`- **${row.plugin}** — declared ${declared}/${row.ids.length}${open.length ? `; OPEN: ${open.join(", ")}` : ""}`);
}

console.log("");
console.log(`## totals — ${openAudience} gesture route(s) and ${openDestructive} destructive-class verb(s) still undeclared AT SOURCE`);
